#!/usr/bin/env python3
"""Real daemon/PTy paste staging isolation; generated bytes only."""
import argparse,json,os,subprocess,sys,tempfile,time
from pathlib import Path
from spike import Client,eventually
p=argparse.ArgumentParser();p.add_argument('--binary',required=True);p.add_argument('--evidence',required=True);a=p.parse_args()
root=Path(tempfile.mkdtemp(prefix='atomic-paste-',dir=a.evidence));root.chmod(0o700)
env={**os.environ,'HOME':str(root/'home'),'XDG_CONFIG_HOME':str(root/'config'),'XDG_DATA_HOME':str(root/'data')}
for k in ['HOME','XDG_CONFIG_HOME','XDG_DATA_HOME']:Path(env[k]).mkdir(mode=0o700)
sock=root/'control.sock';log=(root/'daemon.log').open('w');daemon=subprocess.Popen([a.binary,'--socket',str(sock),'serve'],env=env,stdout=log,stderr=log)
try:
 eventually(sock.exists)
 with Client(sock) as c,Client(sock) as other:
  receiver=Path(__file__).parents[1]/'fixtures/receiver.py';file=root/'received.bin'
  s=c.call('session.create',{'name':'Generated paste','argv':[sys.executable,str(receiver),str(file)]})
  c.call('pane.wait',{'pane':s['pane'],'contains':'READY','timeout_ms':5000})
  for client in [c,other]:client.call('session.attach',{'session':s['session']})
  c.call('pane.sendText',{'pane':s['pane'],'text':'/paste-on/'})
  eventually(lambda:c.call('client.render')['panes'][0]['grid']['bracketed_paste'])
  before=file.read_bytes();payload='ž'.encode()*524288
  def begin(size):return c.call('client.paste',{'operation':'begin','pane':s['pane'],'bytes':size})['token']
  def op(token,operation,**kw):return c.call('client.paste',{'operation':operation,'token':token,**kw})
  token=begin(len(payload))
  other.call('client.paste',{'operation':'commit','token':token},error='STALE_ID')
  c.call('client.paste',{'operation':'chunk','token':token,'offset':1,'text':'x'},error='INVALID_PARAMS')
  for n in range(0,len(payload),32768):op(token,'chunk',offset=n,text=payload[n:n+32768].decode())
  time.sleep(.1);assert file.read_bytes()==before,'Staged paste leaked before commit'
  op(token,'commit');expected=before+b'\x1b[200~'+payload+b'\x1b[201~'
  eventually(lambda:file.read_bytes()==expected,15)
  c.call('client.paste',{'operation':'commit','token':token},error='STALE_ID')
  token=begin(4);op(token,'chunk',offset=0,text='xx');op(token,'abort')
  token=begin(4);op(token,'chunk',offset=0,text='xx');c.call('client.paste',{'operation':'commit','token':token},error='INCOMPLETE_PASTE')
  token=begin(6);op(token,'chunk',offset=0,text='\x1b[20');op(token,'chunk',offset=4,text='1~');c.call('client.paste',{'operation':'commit','token':token},error='INVALID_TEXT')
  c.call('client.paste',{'operation':'begin','pane':s['pane'],'bytes':1048577},error='INVALID_PARAMS')
  token=begin(1);op(token,'chunk',offset=0,text='x');c.call('session.detach');c.call('session.attach',{'session':s['session']});c.call('client.paste',{'operation':'commit','token':token},error='STALE_ID')
  connections=[]
  try:
   for _ in range(16):
    peer=Client(sock);connections.append(peer);peer.call('session.attach',{'session':s['session']})
    peer.call('client.paste',{'operation':'begin','pane':s['pane'],'bytes':1})
   c.call('client.paste',{'operation':'begin','pane':s['pane'],'bytes':1},error='LIMIT')
  finally:
   for peer in connections:peer.close()
  eventually(lambda:c.call('health')['clients']==2)
  token=begin(1);op(token,'chunk',offset=0,text='x')
  # Real elapsed deadline: staged input must not leak when the owner disappears.
  time.sleep(31)
  c.call('client.paste',{'operation':'commit','token':token},error='STALE_ID')
  time.sleep(.1);assert file.read_bytes()==expected,'Rejected or aborted paste delivered input' 
  result={'status':'PASS','single_1MiB_UTF8_bracketed_paste':True,'no_staging_input':True,'other_connection_refused':True,'offset_and_size_limits':True,'duplicate_commit_refused':True,'abort_incomplete_split_marker_detach_no_input':True,'global_staging_limit_disconnect_and_deadline':True,'scope':'Disposable actual daemon/PTy; no physical input claim'}
  (root/'acceptance.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
finally:
 daemon.terminate()
 try:daemon.wait(timeout=8)
 except subprocess.TimeoutExpired:daemon.kill();daemon.wait()
 log.close()
